-- MUÑIZ · Fase 4b · TICKETS DE ESTACIÓN (Leo's, agosto 2026) + placas. Rerunnable.
create table if not exists station_tickets (
  id bigint generated always as identity primary key,
  station text not null default 'LEOS', ticket_date date not null, amount numeric not null, gallons numeric, fuel_type text,
  job_hand text, plate_raw text, plate text, po_raw text, po_found boolean, creator text, project text, po_vendor text, po_date date,
  flags text[] not null default '{}', source text, unique (station, ticket_date, amount, gallons, po_raw));
create table if not exists vehicle_plates (
  plate text primary key, person text, vehicle_id text, fuel_seen text, tickets int, confidence text, note text, source text);
alter table vehicles add column if not exists comb_verified text;
delete from station_tickets where source = 'Leos_Agosto_2026.pdf';
update vehicles set plate = 'NXM4820' where id = 'V-ECH' and coalesce(plate,'') = '';
update vehicles set comb = 'GASOLINA', comb_verified = 'Leo''s ago 2026: 6 tickets GASOLINA' where id = 'V-ECH';
update vehicles set plate = 'VPK0297' where id = 'P-EVA' and coalesce(plate,'') = '';
