alter table station_tickets enable row level security; alter table vehicle_plates enable row level security;
drop policy if exists station_tickets_office on station_tickets; create policy station_tickets_office on station_tickets for all using (is_office()) with check (is_office()); grant all on station_tickets to authenticated;
drop policy if exists vehicle_plates_office on vehicle_plates; create policy vehicle_plates_office on vehicle_plates for all using (is_office()) with check (is_office()); grant all on vehicle_plates to authenticated;
grant usage, select on all sequences in schema public to authenticated;
select 'OK · tickets Leo''s agosto' as status, count(*) tickets, sum(amount) total, count(*) filter (where cardinality(flags)>0) con_bandera from station_tickets where source='Leos_Agosto_2026.pdf';
select id, assigned_to, plate, comb, comb_verified from vehicles where coalesce(plate,'') <> '' order by assigned_to;